import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import '../../../core/data/astro_repository.dart';import '../../../core/data/local_database.dart';import '../../../core/models/reading.dart';import '../../../core/models/zodiac_sign.dart';import '../../../core/theme/app_theme.dart';import '../../../features/journal/presentation/journal_screen.dart';import '../../../shared/widgets/app_components.dart';
class SearchScreen extends StatefulWidget{const SearchScreen({super.key});@override State<SearchScreen> createState()=>_SearchScreenState();}
class _SearchScreenState extends State<SearchScreen>{String query='';List<Map<String,Object?>> saved=[],journal=[];List<HoroscopeReading> readings=[];Future<void> _search(String v)async{query=v;saved=await AstroRepository.instance.saved();journal=await AstroRepository.instance.journal(query:v);final db=await LocalDatabase.instance.database;final cache=await db.query('content_cache');final found=<HoroscopeReading>[];try{final bundled=jsonDecode(await rootBundle.loadString('assets/content/daily-2026-11-18.json')) as Map<String,dynamic>;for(final raw in bundled['readings'] as List){found.add(HoroscopeReading.fromJson({...Map<String,dynamic>.from(raw),'date':bundled['date']}));}}catch(_){}for(final row in cache){try{final doc=jsonDecode(row['payload'] as String);if(doc is Map&&doc['readings'] is List){for(final raw in doc['readings']){found.add(HoroscopeReading.fromJson(Map<String,dynamic>.from(raw)));}}}catch(_){}}final unique={for(final item in found)item.id:item}.values.toList();readings=unique;if(mounted)setState((){});}
@override Widget build(BuildContext context){final signs=zodiacSigns.where((s)=>query.isNotEmpty&&[s.name,s.element,s.modality,s.about].join(' ').toLowerCase().contains(query.toLowerCase())).toList();return Scaffold(appBar:AppBar(title:const Text('Search AstroDaily')),body:ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('Find something to explore'),TextField(onChanged:_search,decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search signs, saved readings and journal')),const SizedBox(height:14),for(final s in signs)ListTile(leading:Text(s.glyph,style:const TextStyle(fontSize:24,color:AppTheme.primary)),title:Text(s.name),subtitle:Text(s.element+' · '+s.modality)),for(final reading in readings.where((r)=>[r.title,r.body,r.category,r.signId].join(' ').toLowerCase().contains(query.toLowerCase())))ListTile(leading:const Icon(Icons.auto_awesome_outlined),title:Text(reading.title),subtitle:Text(reading.signId+' · '+reading.periodStart)),for(final r in saved.where((r)=>[r['title'],r['body']].join(' ').toLowerCase().contains(query.toLowerCase())))ListTile(leading:const Icon(Icons.bookmark_outline),title:Text(r['title'] as String? ?? ''),subtitle:const Text('Saved reading')),for(final j in journal)ListTile(leading:const Icon(Icons.lock_outline),title:Text(j['day'] as String),subtitle:Text(j['body'] as String,maxLines:1),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>JournalScreen(prompt:j['prompt'] as String,entry:j)))),if(query.isNotEmpty&&signs.isEmpty&&saved.isEmpty&&journal.isEmpty&&readings.isEmpty)const InfoCard('No matching cached content found.') ]));}
}
